def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    opp_c = 0
    opp_d = 0
    my_d = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'D':
            my_d += 1

    last_me, last_opp = history[-1]

    if opp_d / n > 0.6:
        return 'D'

    if n == 99:
        return 'D'

    if n >= 95:
        if opp_c >= n - 2 and my_d > 0 and opp_d == 0:
            return 'D'
        if last_me == 'D':
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if opp_d == 0 and my_d == 0:
        if n == 5:
            return 'D'
        return 'C'

    if my_d > 0 and opp_d == 0:
        if n <= 7:
            return 'C'
        if n >= 95:
            return 'D'
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    if last_me == 'D':
        return 'C'

    if last_opp == 'D':
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'

    return 'C'
